def add_script_to_evaluate_on_new_document(
        source: str,
        world_name: str | None = None,
        include_command_line_api: bool | None = None,
        run_immediately: bool | None = None,
) -> typing.Generator[T_JSON_DICT, T_JSON_DICT, ScriptIdentifier]:
    '''Evaluates given script in every frame upon creation (before loading frame's scripts).

    :param source:
    :param world_name: *(Optional)* If specified, creates an isolated world with the given name and evaluates given script in it. This world name will be used as the ExecutionContextDescription::name when the corresponding event is emitted. *(EXPERIMENTAL)*
    :param include_command_line_api: *(Optional)* Specifies whether command line API should be available to the script, defaults to false. *(EXPERIMENTAL)*
    :param run_immediately: *(Optional)* If true, runs the script immediately on existing execution contexts or worlds. Default: false. *(EXPERIMENTAL)*
    :returns: Identifier of the added script.
    '''
    params: T_JSON_DICT = {}
    params['source'] = source
    if world_name is not None:
        params['worldName'] = world_name
    if include_command_line_api is not None:
        params['includeCommandLineAPI'] = include_command_line_api
    if run_immediately is not None:
        params['runImmediately'] = run_immediately
    json = yield {'method': 'Page.addScriptToEvaluateOnNewDocument', 'params': params}
    return ScriptIdentifier.from_json(json['identifier'])


