    not_restored_explanations: list[BackForwardCacheNotRestoredExplanation]
    #: *(Optional)* Tree structure of reasons why the page could not be cached for each frame.
    not_restored_explanations_tree: BackForwardCacheNotRestoredExplanationTree | None = None

    @classmethod
    def from_json(cls, json: T_JSON_DICT) -> BackForwardCacheNotUsed:
        return cls(
            loader_id=network.LoaderId.from_json(json['loaderId']),
            frame_id=FrameId.from_json(json['frameId']),
            not_restored_explanations=[BackForwardCacheNotRestoredExplanation.from_json(i) for i in json['notRestoredExplanations']],
            not_restored_explanations_tree=BackForwardCacheNotRestoredExplanationTree.from_json(json['notRestoredExplanationsTree']) if json.get('notRestoredExplanationsTree') is not None else None,
        )


